-- Evidence-grade reconciliation between an approved request, selected quote, delivery and receipt.
alter table public.attachments drop constraint attachments_related_entity_type_check,
  add constraint attachments_related_entity_type_check check(related_entity_type in ('diary_entry','delay_event','worker_checkin','attachment','weather_snapshot','site_task','project_rfi','worker_credential','site_incident','material_delivery'));
alter table public.notifications drop constraint notifications_notification_type_check,
  add constraint notifications_notification_type_check check(notification_type in ('worker_join','material_request','request_status','site_task','task_review','task_assignment','task_comment','client_decision','change_order_decision','supplier_quote','site_incident','material_delivery'));

create table public.material_deliveries(
  id text primary key,owner_id uuid not null references auth.users(id) on delete cascade,project_id uuid not null references public.projects(id) on delete cascade,
  request_id text not null references public.material_requests(id) on delete cascade,quote_id text references public.material_supplier_quotes(id) on delete set null,
  supplier_name text not null check(char_length(trim(supplier_name)) between 2 and 160),delivery_note_number text check(delivery_note_number is null or char_length(trim(delivery_note_number)) between 1 and 100),
  delivered_at timestamptz not null,receiver_worker_id uuid references public.project_workers(id) on delete set null,receiver_name text not null check(char_length(trim(receiver_name)) between 2 and 180),
  note text check(note is null or char_length(trim(note)) between 1 and 1000),attachment_id text references public.attachments(id) on delete set null,
  status text not null default 'reported' check(status in('reported','accepted','discrepancy','resolved')),reviewed_at timestamptz,reviewed_by uuid references auth.users(id) on delete set null,
  resolution text check(resolution is null or char_length(trim(resolution)) between 5 and 1000),resolved_at timestamptz,resolved_by uuid references auth.users(id) on delete set null,
  created_at timestamptz not null default now(),updated_at timestamptz not null default now(),
  check((status='reported' and reviewed_at is null and reviewed_by is null and resolution is null and resolved_at is null and resolved_by is null) or(status in('accepted','discrepancy') and reviewed_at is not null and reviewed_by is not null and resolution is null and resolved_at is null and resolved_by is null)or(status='resolved' and reviewed_at is not null and reviewed_by is not null and resolution is not null and resolved_at is not null and resolved_by is not null))
);
create table public.material_delivery_lines(
  id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id) on delete cascade,project_id uuid not null references public.projects(id) on delete cascade,delivery_id text not null references public.material_deliveries(id) on delete cascade,
  request_item_id text not null references public.material_request_items(id) on delete restrict,item_name text not null,unit text not null,expected_quantity numeric not null check(expected_quantity>0),delivered_quantity numeric not null check(delivered_quantity>=0),damaged_quantity numeric not null default 0 check(damaged_quantity>=0 and damaged_quantity<=delivered_quantity),created_at timestamptz not null default now(),unique(delivery_id,request_item_id)
);
create table public.material_delivery_events(
  id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id) on delete cascade,project_id uuid not null references public.projects(id) on delete cascade,delivery_id text not null references public.material_deliveries(id) on delete cascade,
  event_type text not null check(event_type in('reported','updated','accepted','discrepancy','resolved')),body text check(body is null or char_length(trim(body)) between 1 and 1000),metadata jsonb not null default'{}',actor_user_id uuid references auth.users(id) on delete set null,actor_worker_id uuid references public.project_workers(id) on delete set null,created_at timestamptz not null default now()
);
create index material_deliveries_project_status_idx on public.material_deliveries(project_id,status,delivered_at desc);create index material_deliveries_request_idx on public.material_deliveries(request_id,delivered_at desc);create index material_delivery_events_timeline_idx on public.material_delivery_events(delivery_id,created_at,id);

alter table public.material_deliveries enable row level security;alter table public.material_delivery_lines enable row level security;alter table public.material_delivery_events enable row level security;
create policy material_deliveries_participant_select on public.material_deliveries for select using((owner_id=auth.uid() and public.owns_project(project_id,auth.uid()))or exists(select 1 from public.project_workers w where w.id=receiver_worker_id and w.auth_user_id=auth.uid()));
create policy material_delivery_lines_participant_select on public.material_delivery_lines for select using((owner_id=auth.uid() and public.owns_project(project_id,auth.uid()))or exists(select 1 from public.material_deliveries d join public.project_workers w on w.id=d.receiver_worker_id where d.id=material_delivery_lines.delivery_id and w.auth_user_id=auth.uid()));
create policy material_delivery_events_participant_select on public.material_delivery_events for select using((owner_id=auth.uid() and public.owns_project(project_id,auth.uid()))or exists(select 1 from public.material_deliveries d join public.project_workers w on w.id=d.receiver_worker_id where d.id=material_delivery_events.delivery_id and w.auth_user_id=auth.uid()));

create function public.guard_material_delivery_change()returns trigger language plpgsql set search_path=public as $$begin if tg_op='DELETE' and(pg_trigger_depth()>1 or not exists(select 1 from public.projects where id=old.project_id))then return old;end if;if current_setting('app.material_delivery_rpc',true)is distinct from'1'then raise exception'MATERIAL_DELIVERY_RPC_REQUIRED';end if;return case when tg_op='DELETE'then old else new end;end$$;
create trigger material_deliveries_guard before insert or update or delete on public.material_deliveries for each row execute function public.guard_material_delivery_change();create trigger material_delivery_lines_guard before insert or update or delete on public.material_delivery_lines for each row execute function public.guard_material_delivery_change();
create function public.guard_material_delivery_event_change()returns trigger language plpgsql set search_path=public as $$begin if tg_op='DELETE' and(pg_trigger_depth()>1 or not exists(select 1 from public.material_deliveries where id=old.delivery_id))then return old;end if;raise exception'MATERIAL_DELIVERY_EVENT_IMMUTABLE';end$$;
create trigger material_delivery_events_immutable before update or delete on public.material_delivery_events for each row execute function public.guard_material_delivery_event_change();

create function public.validate_material_delivery_lines(p_request_id text,p_lines jsonb)returns void language plpgsql security definer set search_path=public as $$declare line jsonb;begin if jsonb_typeof(p_lines)<>'array'or jsonb_array_length(p_lines)not between 1 and 100 then raise exception'INVALID_DELIVERY_LINES';end if;for line in select value from jsonb_array_elements(p_lines)loop if not exists(select 1 from public.material_request_items i where i.id=line->>'requestItemId' and i.request_id=p_request_id and i.name=line->>'itemName' and i.unit=line->>'unit')or coalesce((line->>'expectedQuantity')::numeric,0)<=0 or coalesce((line->>'deliveredQuantity')::numeric,-1)<0 or coalesce((line->>'damagedQuantity')::numeric,-1)<0 or(line->>'damagedQuantity')::numeric>(line->>'deliveredQuantity')::numeric then raise exception'INVALID_DELIVERY_LINE';end if;end loop;end$$;
create function public.write_material_delivery_lines(p_delivery public.material_deliveries,p_lines jsonb)returns void language plpgsql security definer set search_path=public as $$declare line jsonb;begin delete from public.material_delivery_lines where delivery_id=p_delivery.id;for line in select value from jsonb_array_elements(p_lines)loop insert into public.material_delivery_lines(owner_id,project_id,delivery_id,request_item_id,item_name,unit,expected_quantity,delivered_quantity,damaged_quantity)values(p_delivery.owner_id,p_delivery.project_id,p_delivery.id,line->>'requestItemId',line->>'itemName',line->>'unit',(line->>'expectedQuantity')::numeric,(line->>'deliveredQuantity')::numeric,(line->>'damagedQuantity')::numeric);end loop;end$$;

create function public.save_material_delivery(p_id text,p_request_id text,p_supplier_name text,p_delivery_note_number text,p_delivered_at timestamptz,p_receiver_worker_id uuid,p_receiver_name text,p_note text,p_attachment_id text,p_lines jsonb,p_confirmed boolean)returns public.material_deliveries language plpgsql security definer set search_path=public,auth as $$declare uid uuid:=auth.uid();req public.material_requests%rowtype;quote_id text;existing public.material_deliveries%rowtype;result public.material_deliveries%rowtype;event_name text;begin
 if not coalesce(p_confirmed,false)then raise exception'MATERIAL_DELIVERY_CONFIRMATION_REQUIRED';end if;select*into req from public.material_requests where id=p_request_id and owner_id=uid for update;if req.id is null or not public.owns_project(req.project_id,uid)then raise exception'MATERIAL_REQUEST_SCOPE';end if;if req.status not in('approved','partially_purchased','purchased')then raise exception'MATERIAL_REQUEST_NOT_APPROVED';end if;
 if char_length(trim(p_id))<2 or char_length(trim(p_supplier_name))not between 2 and 160 or char_length(trim(p_receiver_name))not between 2 and 180 or char_length(coalesce(p_note,''))>1000 then raise exception'INVALID_MATERIAL_DELIVERY';end if;perform public.validate_material_delivery_lines(p_request_id,p_lines);select id into quote_id from public.material_supplier_quotes where request_id=p_request_id and status='selected';
 if p_receiver_worker_id is not null and not exists(select 1 from public.project_workers where id=p_receiver_worker_id and project_id=req.project_id and owner_id=uid)then raise exception'WORKER_NOT_IN_PROJECT';end if;if p_attachment_id is not null and not exists(select 1 from public.attachments where id=p_attachment_id and owner_id=uid and project_id=req.project_id and related_entity_type='material_delivery' and related_entity_id=p_id)then raise exception'DELIVERY_ATTACHMENT_INVALID';end if;
 select*into existing from public.material_deliveries where id=p_id for update;if existing.id is not null and(existing.owner_id<>uid or existing.request_id<>p_request_id or existing.status<>'reported')then raise exception'MATERIAL_DELIVERY_NOT_EDITABLE';end if;perform set_config('app.material_delivery_rpc','1',true);
 if existing.id is null then insert into public.material_deliveries(id,owner_id,project_id,request_id,quote_id,supplier_name,delivery_note_number,delivered_at,receiver_worker_id,receiver_name,note,attachment_id)values(trim(p_id),uid,req.project_id,p_request_id,quote_id,trim(p_supplier_name),nullif(trim(p_delivery_note_number),''),p_delivered_at,p_receiver_worker_id,trim(p_receiver_name),nullif(trim(p_note),''),p_attachment_id)returning*into result;event_name:='reported';else update public.material_deliveries set supplier_name=trim(p_supplier_name),delivery_note_number=nullif(trim(p_delivery_note_number),''),delivered_at=p_delivered_at,receiver_worker_id=p_receiver_worker_id,receiver_name=trim(p_receiver_name),note=nullif(trim(p_note),''),attachment_id=p_attachment_id,updated_at=now()where id=p_id returning*into result;event_name:='updated';end if;
 perform public.write_material_delivery_lines(result,p_lines);insert into public.material_delivery_events(owner_id,project_id,delivery_id,event_type,metadata,actor_user_id)values(uid,result.project_id,result.id,event_name,jsonb_build_object('lineCount',jsonb_array_length(p_lines)),uid);return result;end$$;

create function public.report_my_material_delivery(p_worker_id uuid,p_request_id text,p_supplier_name text,p_delivery_note_number text,p_delivered_at timestamptz,p_note text,p_lines jsonb,p_confirmed boolean)returns public.material_deliveries language plpgsql security definer set search_path=public,auth as $$declare uid uuid:=auth.uid();worker public.project_workers%rowtype;req public.material_requests%rowtype;result public.material_deliveries%rowtype;delivery_id text:='delivery-'||gen_random_uuid()::text;quote_id text;begin
 if not coalesce(p_confirmed,false)then raise exception'MATERIAL_DELIVERY_CONFIRMATION_REQUIRED';end if;select*into worker from public.project_workers where id=p_worker_id and auth_user_id=uid and status='active';if worker.id is null then raise exception'WORKER_ACCESS_DENIED';end if;select*into req from public.material_requests where id=p_request_id and project_id=worker.project_id and worker_id=worker.id and status in('approved','partially_purchased','purchased');if req.id is null then raise exception'MATERIAL_REQUEST_SCOPE';end if;if char_length(trim(p_supplier_name))not between 2 and 160 or char_length(coalesce(p_note,''))>1000 then raise exception'INVALID_MATERIAL_DELIVERY';end if;perform public.validate_material_delivery_lines(p_request_id,p_lines);select id into quote_id from public.material_supplier_quotes where request_id=p_request_id and status='selected';perform set_config('app.material_delivery_rpc','1',true);
 insert into public.material_deliveries(id,owner_id,project_id,request_id,quote_id,supplier_name,delivery_note_number,delivered_at,receiver_worker_id,receiver_name,note)values(delivery_id,worker.owner_id,worker.project_id,p_request_id,quote_id,trim(p_supplier_name),nullif(trim(p_delivery_note_number),''),p_delivered_at,worker.id,trim(worker.first_name)||' '||trim(worker.last_name),nullif(trim(p_note),''))returning*into result;perform public.write_material_delivery_lines(result,p_lines);insert into public.material_delivery_events(owner_id,project_id,delivery_id,event_type,metadata,actor_user_id,actor_worker_id)values(result.owner_id,result.project_id,result.id,'reported',jsonb_build_object('lineCount',jsonb_array_length(p_lines),'source','worker'),uid,worker.id);insert into public.notifications(recipient_user_id,worker_id,notification_type,title,body,data)values(worker.owner_id,worker.id,'material_delivery','Nová dodávka na kontrolu',result.receiver_name||' prevzal dodávku od '||result.supplier_name,jsonb_build_object('deliveryId',result.id,'projectId',result.project_id,'requestId',result.request_id));return result;end$$;

create function public.review_material_delivery(p_delivery_id text,p_decision text,p_confirmed boolean)returns public.material_deliveries language plpgsql security definer set search_path=public,auth as $$declare uid uuid:=auth.uid();has_issue boolean;result public.material_deliveries%rowtype;begin if not coalesce(p_confirmed,false)then raise exception'MATERIAL_DELIVERY_REVIEW_CONFIRMATION_REQUIRED';end if;if p_decision not in('accepted','discrepancy')then raise exception'INVALID_DELIVERY_DECISION';end if;select exists(select 1 from public.material_delivery_lines where delivery_id=p_delivery_id and(delivered_quantity<>expected_quantity or damaged_quantity>0))into has_issue;if(p_decision='accepted'and has_issue)or(p_decision='discrepancy'and not has_issue)then raise exception'DELIVERY_DECISION_MISMATCH';end if;perform set_config('app.material_delivery_rpc','1',true);update public.material_deliveries set status=p_decision,reviewed_at=now(),reviewed_by=uid,updated_at=now()where id=p_delivery_id and owner_id=uid and status='reported'and public.owns_project(project_id,uid)returning*into result;if result.id is null then raise exception'MATERIAL_DELIVERY_NOT_REVIEWABLE';end if;insert into public.material_delivery_events(owner_id,project_id,delivery_id,event_type,metadata,actor_user_id)values(uid,result.project_id,result.id,p_decision,jsonb_build_object('hasDiscrepancy',has_issue),uid);return result;end$$;
create function public.resolve_material_delivery(p_delivery_id text,p_resolution text,p_confirmed boolean)returns public.material_deliveries language plpgsql security definer set search_path=public,auth as $$declare uid uuid:=auth.uid();result public.material_deliveries%rowtype;begin if not coalesce(p_confirmed,false)then raise exception'MATERIAL_DELIVERY_RESOLUTION_CONFIRMATION_REQUIRED';end if;if char_length(trim(p_resolution))not between 5 and 1000 then raise exception'DELIVERY_RESOLUTION_REQUIRED';end if;perform set_config('app.material_delivery_rpc','1',true);update public.material_deliveries set status='resolved',resolution=trim(p_resolution),resolved_at=now(),resolved_by=uid,updated_at=now()where id=p_delivery_id and owner_id=uid and status='discrepancy'and public.owns_project(project_id,uid)returning*into result;if result.id is null then raise exception'MATERIAL_DELIVERY_NOT_RESOLVABLE';end if;insert into public.material_delivery_events(owner_id,project_id,delivery_id,event_type,body,actor_user_id)values(uid,result.project_id,result.id,'resolved',trim(p_resolution),uid);return result;end$$;

revoke insert,update,delete on public.material_deliveries,public.material_delivery_lines,public.material_delivery_events from public,anon,authenticated;grant select on public.material_deliveries,public.material_delivery_lines,public.material_delivery_events to authenticated;
revoke execute on function public.validate_material_delivery_lines(text,jsonb),public.write_material_delivery_lines(public.material_deliveries,jsonb),public.save_material_delivery(text,text,text,text,timestamptz,uuid,text,text,text,jsonb,boolean),public.report_my_material_delivery(uuid,text,text,text,timestamptz,text,jsonb,boolean),public.review_material_delivery(text,text,boolean),public.resolve_material_delivery(text,text,boolean)from public,anon;grant execute on function public.save_material_delivery(text,text,text,text,timestamptz,uuid,text,text,text,jsonb,boolean),public.report_my_material_delivery(uuid,text,text,text,timestamptz,text,jsonb,boolean),public.review_material_delivery(text,text,boolean),public.resolve_material_delivery(text,text,boolean)to authenticated;
create trigger material_deliveries_audit after insert or update or delete on public.material_deliveries for each row execute function public.audit_row();create trigger material_delivery_lines_audit after insert or update or delete on public.material_delivery_lines for each row execute function public.audit_row();create trigger material_delivery_events_audit after insert or update or delete on public.material_delivery_events for each row execute function public.audit_row();
alter function public.export_my_data()rename to export_my_data_v22;create function public.export_my_data()returns jsonb language sql stable security definer set search_path=public,auth as $$select case when auth.uid()is null then null else public.export_my_data_v22()||jsonb_build_object('schemaVersion',23,'materialDeliveries',coalesce((select jsonb_agg(to_jsonb(x)order by x.delivered_at,x.id)from public.material_deliveries x where x.owner_id=auth.uid()),'[]'::jsonb),'materialDeliveryLines',coalesce((select jsonb_agg(to_jsonb(x)order by x.created_at,x.id)from public.material_delivery_lines x where x.owner_id=auth.uid()),'[]'::jsonb),'materialDeliveryEvents',coalesce((select jsonb_agg(to_jsonb(x)order by x.created_at,x.id)from public.material_delivery_events x where x.owner_id=auth.uid()),'[]'::jsonb))end$$;revoke execute on function public.export_my_data()from public,anon;grant execute on function public.export_my_data()to authenticated;
